#root,[data-slot="sidebar-wrapper"],[data-slot="sidebar"],[data-slot="sidebar-gap"],[data-slot="sidebar-container"],[data-slot="sidebar-inset"],:has(> [data-chat-column]),[data-chat-column],[data-workspace-area="conversation"],[data-workspace-area="composer"],.messages-timeline-scroll,[data-timeline-row-kind]{background:transparent !important}
[data-timeline-root]{position:relative;isolation:isolate}
[data-timeline-root]::before{content:"";position:absolute;inset:-6px 0;z-index:-1;pointer-events:none;backdrop-filter:blur(16px) brightness(.86);-webkit-mask-image:linear-gradient(90deg,transparent,#000 70px,#000 calc(100% - 70px),transparent);mask-image:linear-gradient(90deg,transparent,#000 70px,#000 calc(100% - 70px),transparent)}
[data-slot="sidebar-inset"]::before,[data-slot="sidebar-inset"]::after{display:none !important}
[data-slot="sidebar-inner"]{background:rgba(10,16,22,.45) !important;backdrop-filter:blur(22px) saturate(1.2);border:1px solid rgba(255,255,255,.08) !important;border-radius:14px;margin:8px;height:calc(100% - 16px) !important;box-shadow:0 10px 40px -12px rgba(0,0,0,.6)}
[data-chat-header]{background:rgba(8,14,20,.25) !important;backdrop-filter:blur(14px);border-bottom:1px solid rgba(255,255,255,.06) !important}
[data-slot="composer-shell"]::before,[data-slot="composer-host"]::before{background:rgba(10,16,22,.4) !important;backdrop-filter:blur(22px) saturate(1.2) !important}
[data-slot="composer-host"] textarea,[data-slot="composer-host"] [contenteditable]{background:transparent !important}
[data-slot="composer-host"]{background:transparent !important;border:1px solid rgba(255,255,255,.13) !important;box-shadow:0 12px 40px -14px rgba(0,0,0,.7),0 0 30px -12px rgba(255,215,150,.15) !important}
[data-slot="composer-host"]:focus-within{border-color:rgba(255,220,160,.4) !important;box-shadow:0 0 34px -8px rgba(255,210,140,.28) !important}
[data-user-message-bubble]{background:rgba(255,255,255,.08) !important;backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,.12) !important}
[data-thread-details-card],[data-slot="dialog-popup"],[data-slot="popover-popup"],[data-slot="menu-popup"]{background:rgba(12,18,24,.65) !important;backdrop-filter:blur(22px) saturate(1.2);border:1px solid rgba(255,255,255,.1) !important;box-shadow:0 16px 44px -12px rgba(0,0,0,.6) !important}
[data-slot="tooltip-popup"]{background:rgba(12,18,24,.85) !important;backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,.1) !important}
[data-thread-item]{border-radius:9px;transition:background-color .2s,box-shadow .2s}
[data-thread-item]:hover{background:rgba(255,255,255,.07) !important;box-shadow:inset 0 0 0 1px rgba(255,220,160,.12)}
[data-slot="button"]:hover{background-color:rgba(255,255,255,.08) !important}
[data-slot="button"]:hover svg.lucide,[data-thread-item]:hover svg.lucide{color:#ffd79a}
[data-slot="menu-popup"] [role="menuitem"]:hover,[data-slot="menu-popup"] [data-highlighted]{background:rgba(255,255,255,.09) !important}
[data-slot="input"],[data-slot="select-trigger"]{background:rgba(255,255,255,.05) !important}
.chat-markdown-codeblock{background:rgba(3,6,10,.55) !important;backdrop-filter:blur(10px);border:1px solid rgba(255,255,255,.07) !important}
.chat-markdown,[data-timeline-row-kind]{text-shadow:0 1px 10px rgba(0,0,0,.6)}
.chat-markdown a{color:#ffd79a !important}
::selection{background:rgba(255,210,140,.35);color:#fff}
::-webkit-scrollbar{width:9px;height:9px}
::-webkit-scrollbar-track{background:transparent}
::-webkit-scrollbar-thumb{background:rgba(255,255,255,.18);border-radius:8px}
[data-slot="scroll-area-thumb"]{background:rgba(255,255,255,.22) !important}
